document.head.insertAdjacentHTML('beforeend','<link rel="stylesheet" href="tablet.css"><link rel="stylesheet" href="verification.css">');
const sports=['Bordtennis','Curling','Fotboll','Golf','Handboll','Ishockey','Kampsport','Konståkning','Motorsport','Ridsport','Tennis','Övrigt'];
const legacySports=['Bordtennis','Curling','Fotboll','Golf','Ishockey','Motorsport','Ridsport','Tennis'];
const channels=[['TV4 Play Sport Total','Fotboll, ishockey, tennis och ridsport'],['Viaplay Total','NHL, europeisk fotboll, golf och motorsport'],['Prime Video','Utvalda Premier League-matcher'],['Disney+','NHL, La Liga och europeisk fotboll'],['HBO Max / Eurosport','Curling, golf och internationell sport'],['SVT','Direktsänd sport på SVT:s tv-kanaler'],['SVT Play','Sport som sänds direkt på SVT Play'],['Kanal 6','Fotboll, ishockey och motorsport'],['Kanal 9','Sport och internationella mästerskap'],['Kanal 12','Sport från TV4:s kanalutbud'],['TV4:s sportkanaler','SHL, Hockeyallsvenskan och studiosändningar'],['V sport-kanaler','Fotboll, NHL, golf och motorsport']];
const events=globalThis.sportGuide?.events||[];
const guideDate=globalThis.sportGuide?.date||'2026-11-01';
const swedishToday=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm'}).format(new Date());
const getPrefs=()=>{const saved=JSON.parse(localStorage.getItem('sportPrefs')||'null');if(saved?.version===4)return saved;if(saved?.version===3){const additions=sports.filter(x=>!legacySports.includes(x));return {version:4,sports:[...new Set([...saved.sports,...additions])],channels:saved.channels}}return {version:4,sports:[...sports],channels:channels.map(x=>x[0])}};
function renderEvents(filter='Alla'){const root=document.querySelector('#events');if(!root)return;const prefs=getPrefs();const allowed=e=>prefs.channels.some(c=>(c.startsWith('TV4')&&(e.service.includes('TV4')||e.channel.includes('TV4')))||(c.startsWith('Viaplay')&&e.service.includes('Viaplay'))||(c==='Prime Video'&&e.service.includes('Amazon Prime'))||(c.startsWith('Disney')&&e.service.includes('Disney'))||(c.startsWith('HBO')&&(e.service.includes('HBO')||e.channel.includes('Eurosport')))||(c==='SVT'&&/^SVT\d|SVT24/.test(e.channel))||(c==='SVT Play'&&(e.service.includes('SVT')||e.channel.includes('SVT Play')))||(c==='Kanal 6'&&e.channel==='Kanal 6')||(c==='Kanal 9'&&e.channel==='Kanal 9')||(c==='Kanal 12'&&e.channel==='Kanal 12')||(c.startsWith('V sport')&&e.channel.startsWith('V sport')));const visible=events.filter(e=>e.date===swedishToday()&&!e.status&&prefs.sports.includes(e.sport)&&allowed(e)&&(filter==='Alla'||e.sport===filter));const eventRow=e=>`<a class="event" href="${e.url}" target="_blank" rel="noreferrer"><span class="time">${e.time}</span><div><span class="sport-label">${e.sport}</span><h4>${e.title}</h4><p>${e.meta}</p></div><div class="channel"><b>${e.channel}</b><span>${e.service}</span></div><span class="arrow">↗</span></a>${e.facts?.length?`<details class="event-facts"><summary>Fakta och källor</summary>${e.facts.map(f=>`<a href="${f.url}" target="_blank" rel="noreferrer">${f.label} ↗</a>`).join(" · ")}</details>`:""}`;if(root.dataset.view==='timeline'){const sorted=[...visible].sort((a,b)=>a.time.localeCompare(b.time)||a.title.localeCompare(b.title,'sv'));root.innerHTML=sorted.map(eventRow).join('')||'<div class="empty">Inga valda sändningar att visa.</div>';const count=document.querySelector('#count');if(count)count.textContent=visible.length;return}const groups=Object.groupBy?Object.groupBy(visible,e=>e.sport):visible.reduce((a,e)=>((a[e.sport]??=[]).push(e),a),{});root.innerHTML=Object.keys(groups).sort((a,b)=>a.localeCompare(b,'sv')).map(s=>`<section class="sport-group"><div class="sport-title"><h3>${s}</h3><span>${groups[s].length} SÄNDNING${groups[s].length>1?'AR':''}</span></div>${groups[s].sort((a,b)=>a.time.localeCompare(b.time)).map(eventRow).join('')}</section>`).join('')||'<div class="empty">Inga valda sändningar att visa.</div>';document.querySelector('#count').textContent=`${visible.length} sändningar`}
document.querySelectorAll('.chip').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderEvents(b.dataset.filter)}));renderEvents();
const timelineView=document.querySelector('[data-view="timeline"]');if(timelineView){requestAnimationFrame(()=>{const rows=[...timelineView.querySelectorAll('.event')];if(!rows.length)return;const now=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());const current=rows.find(row=>row.querySelector('.time').textContent>=now)||rows.at(-1);current.classList.add('current-event');current.scrollIntoView({block:'center'})})}
function renderUpdateTimes(){const updated=document.querySelector('#updated-time'),next=document.querySelector('#next-update-time');if(!updated||!next)return;const checked=globalThis.sportGuide?.checkedAt;updated.textContent=checked?'Kontrollerad '+new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(checked)):'Kontrolldatum saknas';next.textContent=guideDate===swedishToday()?'Alla tider är svensk tid (Europe/Stockholm)':'Dagens tablå är inte verifierad. Senaste underlag: '+guideDate}renderUpdateTimes();document.querySelector('#refresh')?.addEventListener('click',()=>location.reload());
const currentDateLabel=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(swedishToday()+'T12:00:00Z')).toLocaleUpperCase('sv-SE');document.querySelectorAll('.hero .eyebrow,.guide .section-head .eyebrow,.today-hero>.eyebrow').forEach(label=>label.textContent=currentDateLabel);
const guideRoot=document.querySelector('#events');if(guideRoot){const info=document.createElement('p');info.className='verification-note';info.textContent=guideDate===swedishToday()?'Sändningsstart visas i svensk tid. Matchstart kan vara senare.':'Ingen tablå är verifierad för dagens datum. Äldre matcher visas inte som dagens.';guideRoot.before(info);const pending=events.filter(e=>e.date===swedishToday()&&e.status);if(pending.length){const box=document.createElement('details');box.className='verification-note';box.innerHTML='<summary>Ej verifierade sändningsuppgifter ('+pending.length+')</summary><p>Dessa poster ingår inte i dagens verifierade lista. Datum, sändningsstart eller kanal har inte kunnat bekräftas i den officiella programkällan.</p>'+pending.map(e=>'<p><a href="'+e.sourceUrl+'" target="_blank" rel="noreferrer">'+e.title+' · kontrollera källan ↗</a></p>').join('');guideRoot.after(box)}}
function renderSettings(){const form=document.querySelector('#settings-form');if(!form)return;let prefs=getPrefs();const save=()=>{localStorage.setItem('sportPrefs',JSON.stringify(prefs));const s=document.querySelector('#save-status');s.textContent='✓ Ändringar sparade';};document.querySelector('#sports-options').innerHTML=sports.map(x=>`<label class="option"><input type="checkbox" value="${x}" ${prefs.sports.includes(x)?'checked':''}><span>${x}</span></label>`).join('');document.querySelector('#channel-options').innerHTML=channels.map(([x,d])=>`<label class="option"><input type="checkbox" value="${x}" ${prefs.channels.includes(x)?'checked':''}><span>${x}<small>${d}</small></span></label>`).join('');form.addEventListener('change',e=>{const all=[...form.querySelectorAll('input')];prefs={version:4,sports:all.filter(x=>sports.includes(x.value)&&x.checked).map(x=>x.value),channels:all.filter(x=>channels.some(c=>c[0]===x.value)&&x.checked).map(x=>x.value)};save()});document.querySelectorAll('[data-toggle]').forEach(b=>b.addEventListener('click',()=>{const vals=b.dataset.toggle==='sports'?sports:channels.map(x=>x[0]);form.querySelectorAll('input').forEach(i=>{if(vals.includes(i.value))i.checked=true});form.dispatchEvent(new Event('change'));}));}renderSettings();
const updateInterval=document.querySelector('.interval b');if(updateInterval)updateInterval.textContent='Varje hel timme';
